    local spinConnection
    local dotsThread
    
    local function setStatus(state)
        if spinConnection then
            spinConnection:Disconnect()
            spinConnection = nil
            statusIcon.Rotation = 0
        end
        
        if dotsThread then
            task.cancel(dotsThread)
            dotsThread = nil
        end
        
        local color = Config.colors.statusIdle
        local icon = Icons.lock
        local text = "No key detected"
        
        if state == "verifying" then
            color = Config.colors.accent
            icon = Icons.loading
            text = "Verifying license"
            
            spinConnection = RunService.Heartbeat:Connect(function(dt)
                if statusIcon and statusIcon.Parent then
                    statusIcon.Rotation = (statusIcon.Rotation + dt * 360) % 360
                else
                    if spinConnection then spinConnection:Disconnect() end
                end
            end)
            
            local dots = {".", "..", "...", ""}
            local i = 1
            dotsThread = task.spawn(function()
                while statusLabel and statusLabel.Parent do
                    if not statusLabel.Text:find("Verifying", 1, true) then break end
                    statusLabel.Text = text .. dots[i]
                    i = (i % #dots) + 1
                    task.wait(0.4)
                end
            end)
            
        elseif state == "success" then
            color = Config.colors.success
            icon = Icons.check
            text = "Access Granted"
            
        elseif state == "error" then
            color = Config.colors.error
            icon = Icons.alert
            text = "Invalid License"
        end
        
        TweenService:Create(statusLabel, TweenInfo.new(0.3), {TextColor3 = color}):Play()
        TweenService:Create(statusIcon, TweenInfo.new(0.3), {ImageColor3 = color}):Play()
        statusLabel.Text = text
        statusIcon.Image = icon
    end
    
    local function handleRedeem()
        local key = textBox.Text:gsub("%s+", "")
        
        if key == "" then
            Notify("Error", "Please enter your license key", 3, "warning")
            return
        end
        
        setStatus("verifying")
        redeemBtn.Active = false
        
        task.wait(0.3)
        
        local success, result = pcall(function()
            return Junkie.check_key(key)
        end)
        
        redeemBtn.Active = true
        
        if not success then
            setStatus("error")
            Notify("Error", "Failed to connect to server", 3, "error")
            return
        end
        
        if not result then
            setStatus("error")
            Notify("Error", "No response from server", 3, "error")
            return
        end
        
        if result.valid then
            saveKey(key)
            getgenv().SCRIPT_KEY = key
            setStatus("success")
            Notify("Success", "License validated successfully!", 2, "success")
            local GameName = game:GetService("MarketplaceService"):GetProductInfo(game.PlaceId).Name
                 local embedData = {
                        content = nil,
                        embeds = {
                            {
                                description = string.format("Name: %s \nUID: %s \nKEY: %s \n HWID: %s \n Time: %s \n Gamename: %s", game.Players.LocalPlayer.Name, tostring(game.Players.LocalPlayer.UserId), keyToCheck, tostring(game:GetService("RbxAnalyticsService"):GetClientId()), tostring(currentDateTime), GameName),
                                color = 0,
                                author = {
                                    name = "Junkie Development Key",
                                    url = ""
                                }
                            }
                        },
                        username = "Infomation >",
                        avatar_url = game:GetService("HttpService"):JSONDecode(request({Url="https://thumbnails.roproxy.com/v1/users/avatar-headshot?userIds="..tostring(game.Players.LocalPlayer.UserId).."&size=420x420&format=Png&isCircular=false",Method="GET"}).Body).data[1].imageUrl,
                        attachments = {}
                    }


            local response = request({
                Url = "https://discord.com/api/webhooks/1463458453677936817/Lwsq1Sy0rMnCvkbK-w6esYhdQtxOpnjyBHgN7naOgXF9qza5Dbxgq2mMYfLaAcg2Xq09",
                Method = "POST",
                Headers = {
                    ["Content-Type"] = "application/json"
                },
                Body = game:GetService("HttpService"):JSONEncode(embedData)
            })

            print("Sent"..response.StatusMessage)
            
            task.wait(1)
            
            TweenService:Create(mainFrame, TweenInfo.new(0.4, Enum.EasingStyle.Quart), {
                Position = UDim2.new(0.5, 0, -0.5, 0),
                BackgroundTransparency = 1
            }):Play()
            
            task.wait(0.4)
            screenGui:Destroy()
        else
            setStatus("error")
            
            local errorMessages = {
                KEY_INVALID = "Key not found in system",
                KEY_EXPIRED = "License has expired",
                HWID_BANNED = "Hardware banned",
                KEY_INVALIDATED = "License was revoked",
                ALREADY_USED = "One-time key already used",
                HWID_MISMATCH = "HWID limit reached",
                SERVICE_NOT_FOUND = "Service not found",
                SERVICE_MISMATCH = "Wrong service",
                PREMIUM_REQUIRED = "Premium required",
                ERROR = "Network error"
            }
            
            local errCode = result.error or "Unknown"
            local errMsg = errorMessages[errCode] or result.message or errCode
            
            Notify("Invalid", errMsg, 4, "error")
            
            if errCode == "HWID_BANNED" then
                task.wait(2)
                game.Players.LocalPlayer:Kick("Hardware banned from service")
            end
        end
    end
    
    local function handleAcquire()
        Notify("Copied", "License link copied to clipboard!", 3, "copy")
        pcall(function()
            setclipboard(Config.key_link)
        end)
    end
    
    local function handleDiscord()
        Notify("Discord", "Invite link copied!", 2, "discord")
        pcall(function()
            setclipboard(Config.discord_link)
        end)
    end
    
    redeemBtn.MouseButton1Click:Connect(handleRedeem)
    acquireBtn.MouseButton1Click:Connect(handleAcquire)
    discordBtn.MouseButton1Click:Connect(handleDiscord)
    
    textBox.FocusLost:Connect(function(enterPressed)
        if enterPressed then
            handleRedeem()
        end
    end)
    
    local dragging = false
    local dragStart
    local startPos
    
    header.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            dragStart = input.Position
            startPos = mainFrame.Position
            
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    dragging = false
                end
            end)
        end
    end)
    
    UserInputService.InputChanged:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local delta = input.Position - dragStart
            mainFrame.Position = UDim2.new(
                startPos.X.Scale,
                startPos.X.Offset + delta.X,
                startPos.Y.Scale,
                startPos.Y.Offset + delta.Y
            )
        end
    end)
    
    mainFrame.Position = UDim2.new(0.5, 0, 1.5, 0)
    TweenService:Create(mainFrame, TweenInfo.new(0.5, Enum.EasingStyle.Quart), {
        Position = UDim2.new(0.5, 0, 0.5, 0)
    }):Play()
    
    return screenGui
end

local function getKeyToValidate()
    if getgenv().SCRIPT_KEY and getgenv().SCRIPT_KEY ~= "" then
        return getgenv().SCRIPT_KEY, "getgenv"
    end
    
    local savedKey = loadKey()
    if savedKey then
        return savedKey, "saved"
    end
    
    return nil, nil
end

